SELECT a.id, a.customer_id, a.balance, t.credit_amount FROM accounts a INNER JOIN (SELECT account_id, SUM(CASE WHEN txn_type = 'CREDIT' THEN amount ELSE 0 END) AS credit_amount FROM transactions GROUP BY account_id) t ON a.id = t.account_id WHERE t.credit_amount >= 70 ORDER BY a.id DESC, credit_amount DESC;
